'use strict';
const stages=['Consultation','Préopératoire','Intervention','SSPI','Hospitalisation','Sortie'];
const patients=[['DÉMO-001','Orthopédie','Hospitalisation','Préopératoire','Bilan à compléter'],['DÉMO-002','Chirurgie digestive','Hospitalisation','Hospitalisation','Transmission attendue'],['DÉMO-003','ORL','Ambulatoire','Consultation','Consultation à valider'],['DÉMO-004','Gynécologie','Ambulatoire','SSPI','Surveillance en cours'],['DÉMO-005','Urologie','Hospitalisation','Intervention','Dossier disponible'],['DÉMO-006','Orthopédie','Hospitalisation','Sortie','Synthèse à compléter']].map((p,i)=>({id:p[0],specialty:p[1],mode:p[2],stage:p[3],task:p[4],done:false,consult:{asa:'Non renseigné',history:'',allergies:'À vérifier',treatments:'',plan:'',checks:[],validated:false},notes:[],rx:[],discharge:{summary:'',instructions:'',validated:false},events:[{at:'Exemple initial',role:'Démonstration',text:'Séjour fictif créé',kind:'Dossier'}]}));
let selected='DÉMO-001',tab='overview',view='patients',query='',filter='Tous',role='Anesthésiste';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const p=()=>patients.find(x=>x.id===selected);const physician=()=>role!=='Infirmier';
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4000)}
function event(text,kind='Modification'){p().events.unshift({at:new Date().toLocaleString('fr-FR'),role,text,kind})}
function stats(){const pending=patients.filter(x=>!x.done).length;$('#stats').innerHTML=[[patients.length,'Séjours fictifs'],[patients.filter(x=>['Intervention','SSPI','Hospitalisation'].includes(x.stage)).length,'Prises en charge en cours'],[pending,'Actions en attente'],[patients.filter(x=>x.stage==='Sortie').length,'Séjours en sortie']].map((x,i)=>`<div class="stat ${i===2?'accent':''}"><span>${x[1]}</span><strong>${x[0]}</strong></div>`).join('')}
function render(){stats();$('#title').textContent={patients:'Patients & séjours',tasks:'Actions à suivre',integration:'Connexion Emed',portal:'Préparer ma consultation'}[view];document.querySelectorAll('.nav[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(view==='portal'){renderPortal();return}if(view==='tasks'){renderTasks();return}if(view==='integration'){renderIntegration();return}$('#workspace').innerHTML=`<div class="layout"><section class="panel"><div class="panelhead"><h3>Liste des séjours</h3><div class="filters"><input id="search" aria-label="Rechercher un séjour fictif" placeholder="Identifiant ou spécialité" value="${esc(query)}"><select id="filter" aria-label="Filtrer le parcours">${['Tous',...stages].map(s=>`<option ${filter===s?'selected':''}>${s}</option>`).join('')}</select></div></div><div id="patientlist"></div></section><section class="panel" id="detail"></section></div>`;$('#search').oninput=e=>{query=e.target.value;list()};$('#filter').onchange=e=>{filter=e.target.value;list()};list();detail()}
function list(){const matches=patients.filter(x=>(filter==='Tous'||filter===x.stage)&&`${x.id} ${x.specialty}`.toLowerCase().includes(query.toLowerCase()));$('#patientlist').innerHTML=matches.length?matches.map(x=>`<button class="patient ${x.id===selected?'selected':''}" data-patient="${x.id}"><div class="row"><strong>${x.id}</strong><span class="pill">${x.stage}</span></div><small>${x.specialty} · ${x.mode}</small><small>${x.done?'Action réalisée':x.task}</small></button>`).join(''):'<div class="empty">Aucun séjour ne correspond à ce filtre.</div>';document.querySelectorAll('[data-patient]').forEach(b=>b.onclick=()=>{selected=b.dataset.patient;tab='overview';list();detail()})}
function detail(){const x=p();$('#detail').innerHTML=`<div class="detailhead"><div class="row"><div><h2>${x.id}</h2><p>${x.specialty} · ${x.mode}</p></div><span class="identity">Patient fictif</span></div><span class="pill ${x.done?'good':'warn'}">${x.done?'Action réalisée':esc(x.task)}</span></div><div class="timeline" aria-label="Étapes du séjour">${stages.map(s=>`<button data-stage="${s}" class="${s===x.stage?'current':''}" ${!physician()?'disabled':''} title="Modifier l’étape simulée">${s}</button>`).join('')}</div><div class="tabs" role="tablist">${[['overview','Synthèse'],['preparation','Préparation'],['questionnaire','Réponses patient'],['consult','Consultation'],['follow','Suivi & SSPI'],['rx','Prescriptions'],['discharge','Sortie'],['instructions','Consignes patient'],['history','Historique']].map(([k,n])=>`<button role="tab" aria-selected="${k===tab}" data-tab="${k}" class="${k===tab?'active':''}">${n}</button>`).join('')}</div><div class="content" id="content"></div>`;document.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>{if(!physician())return;x.stage=b.dataset.stage;event('Étape : '+x.stage,'Parcours');stats();list();detail();toast('Étape du séjour simulée mise à jour')});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{if(tab==='consult')captureConsult();tab=b.dataset.tab;detail()});({overview:overview,preparation:preparation,instructions:patientInstructions,questionnaire:questionnaireReview,consult:consult,follow:follow,rx:prescriptions,discharge:discharge,history:history})[tab]()}
function consult(){const c=p().consult,read=!physician()||c.validated;$('#content').innerHTML=`<h3>Consultation d’anesthésie</h3>${p().questionnaire?`<div class="notice">Questionnaire patient reçu · ${p().questionnaire.reviewed?'Réponses reprises dans le brouillon':'À vérifier'}. <button class="secondary" type="button" id="seeanswers">Voir les réponses</button></div>`:''}<div class="notice">${c.validated?'Consultation validée dans la simulation. Une révision ouvre une nouvelle modification tracée.':'Saisie de démonstration. Aucun calcul de risque ni recommandation thérapeutique automatique.'}</div><form id="consultform"><fieldset ${read?'disabled':''} style="border:0;margin:0;padding:0"><div class="formgrid"><label>Classe ASA<select name="asa">${['Non renseigné','I','II','III','IV','V','VI'].map(v=>`<option ${v===c.asa?'selected':''}>${v}</option>`).join('')}</select></label><label>Allergies / statut de vérification<input name="allergies" value="${esc(c.allergies)}" placeholder="Données fictives uniquement"></label><label>Antécédents<textarea name="history">${esc(c.history)}</textarea></label><label>Traitements habituels<textarea name="treatments">${esc(c.treatments)}</textarea></label><label class="wide">Évaluation et préparation préopératoire<textarea name="plan">${esc(c.plan)}</textarea></label></div>${['Identité vérifiée dans le scénario','Allergies revues','Traitements revus','Examens et documents revus'].map(s=>`<label class="check"><input type="checkbox" name="checks" value="${s}" ${c.checks.includes(s)?'checked':''}>${s}</label>`).join('')}</fieldset><div class="actions"><button class="primary" ${read?'disabled':''} name="action" value="save">Enregistrer le brouillon</button><button class="secondary" ${read?'disabled':''} name="action" value="validate">Simuler la validation</button>${c.validated&&physician()?'<button class="secondary" type="button" id="revise">Ouvrir une révision</button>':''}</div></form><p class="muted">${read&&!c.validated?'Lecture seule dans le profil infirmier.':''}</p>`;$('#consultform').onsubmit=e=>{e.preventDefault();if(read)return;const f=new FormData(e.currentTarget);Object.assign(c,Object.fromEntries(['asa','history','allergies','treatments','plan'].map(k=>[k,f.get(k)])));c.checks=f.getAll('checks');c.validated=e.submitter.value==='validate';event(c.validated?'Consultation validée (simulation)':'Brouillon de consultation enregistré','Consultation');detail();toast('Consultation enregistrée pour cette session')};if($('#seeanswers'))$('#seeanswers').onclick=()=>{tab='questionnaire';detail()};if($('#revise'))$('#revise').onclick=()=>{c.validated=false;event('Révision de consultation ouverte','Consultation');detail()}}
function follow(){$('#content').innerHTML=`<h3>Suivi clinique & transmissions</h3><form id="noteform"><div class="formgrid"><label>Contexte<select name="context"><option>Transmission</option><option>SSPI</option><option>Visite postopératoire</option><option>Hospitalisation</option><option>Événement à signaler</option></select></label><label>Douleur — valeur saisie, /10<input name="pain" type="number" min="0" max="10" step="1" placeholder="Non renseignée"></label><label class="wide">Observation fictive<textarea name="note" required placeholder="Observation, surveillance ou tâche à transmettre"></textarea></label></div><button class="primary">Enregistrer la transmission</button></form><h3 style="margin-top:26px">Dernières transmissions</h3>${p().notes.length?p().notes.map(n=>`<div class="event"><strong>${esc(n.context)} · ${esc(n.role)}</strong><p>${esc(n.note)}</p><p>${n.pain!==''?'Douleur saisie : '+esc(n.pain)+'/10':''}</p><time>${esc(n.at)}</time></div>`).join(''):'<p class="muted">Aucune transmission saisie.</p>'}`;$('#noteform').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget),n={...Object.fromEntries(f),role,at:new Date().toLocaleString('fr-FR')};p().notes.unshift(n);event('Transmission ajoutée : '+n.context,'Suivi');detail();toast('Transmission enregistrée')}}
function prescriptions(){$('#content').innerHTML=`<h3>Préparation des prescriptions</h3><div class="notice warn">Simulation uniquement — aucune valeur d’ordonnance. Aucun schéma thérapeutique proposé ou validé cliniquement. Les prescriptions ne sont pas envoyées à Emed.</div>${physician()?`<form id="rxform"><div class="formgrid"><label>Libellé de démonstration<input name="name" required placeholder="Ex. Prescription fictive A"></label><label>Catégorie<select name="category"><option>Médicament</option><option>Examen biologique</option><option>Surveillance</option><option>Soin infirmier</option></select></label><label class="wide">Consignes de démonstration<textarea name="instructions" required placeholder="Tester la structure : dose, voie, fréquence, durée ou consignes. Aucune donnée réelle."></textarea></label></div><button class="primary">Ajouter au brouillon</button></form>`:'<p class="muted">Profil infirmier : consultation des prescriptions et simulation de réalisation après validation médicale.</p>'}<div id="rxlist">${p().rx.length?p().rx.map((r,i)=>`<article class="rx"><header><strong>${esc(r.name)}</strong><span class="pill ${r.validated?'good':'warn'}">${r.validated?'Validée en simulation':'Brouillon'}</span></header><p class="muted">${esc(r.category)} · ${esc(r.author)}</p><p>${esc(r.instructions)}</p><div class="actions" style="margin-top:12px">${!r.validated&&physician()?`<button class="secondary" data-validate="${i}">Simuler la validation médicale</button>`:''}${r.validated?`<button class="secondary" data-admin="${i}" ${r.administered?'disabled':''}>${r.administered?'Réalisation simulée enregistrée':'Simuler la réalisation'}</button>`:''}</div></article>`).join(''):'<p class="muted" style="margin-top:20px">Aucune prescription de démonstration.</p>'}</div>`;if($('#rxform'))$('#rxform').onsubmit=e=>{e.preventDefault();if(!physician())return;const f=new FormData(e.currentTarget);p().rx.push({...Object.fromEntries(f),author:role,validated:false,administered:false});event('Prescription de démonstration ajoutée au brouillon','Prescription');detail();toast('Brouillon ajouté')};document.querySelectorAll('[data-validate]').forEach(b=>b.onclick=()=>{if(!physician())return;const r=p().rx[+b.dataset.validate];r.validated=true;event('Validation simulée : '+r.name,'Prescription');detail()});document.querySelectorAll('[data-admin]').forEach(b=>b.onclick=()=>{const r=p().rx[+b.dataset.admin];if(!r.validated||r.administered)return;r.administered=true;event('Réalisation simulée : '+r.name,'Prescription');detail();toast('Réalisation enregistrée dans la simulation')})}
function discharge(){const d=p().discharge,read=!physician()||d.validated;$('#content').innerHTML=`<h3>Synthèse de sortie</h3><form id="dischargeform"><label>Synthèse du séjour<textarea name="summary" ${read?'disabled':''}>${esc(d.summary)}</textarea></label><label>Consignes et suivi prévu<textarea name="instructions" ${read?'disabled':''}>${esc(d.instructions)}</textarea></label><div class="actions"><button class="primary" ${read?'disabled':''} name="action" value="save">Enregistrer la synthèse</button><button class="secondary" ${read?'disabled':''} name="action" value="validate">Simuler la validation de sortie</button></div></form><p class="muted">${d.validated?'Sortie validée dans le scénario. Aucun document médical délivré.':'La validation simulée positionne le séjour à l’étape Sortie.'}</p>`;$('#dischargeform').onsubmit=e=>{e.preventDefault();if(read)return;const f=new FormData(e.currentTarget);d.summary=f.get('summary');d.instructions=f.get('instructions');d.validated=e.submitter.value==='validate';if(d.validated)p().stage='Sortie';event(d.validated?'Sortie validée (simulation)':'Synthèse de sortie enregistrée','Sortie');stats();list();detail();toast('Synthèse enregistrée')}}
function history(){$('#content').innerHTML=`<h3>Historique du scénario</h3><p class="muted">Actions de cette session seulement. Ce journal de démonstration n’est pas un journal d’audit sécurisé.</p>${p().events.map(n=>`<div class="event"><strong>${esc(n.kind)} · ${esc(n.role)}</strong><p>${esc(n.text)}</p><time>${esc(n.at)}</time></div>`).join('')}`}
function renderTasks(){$('#workspace').innerHTML=`<section class="panel"><div class="panelhead"><h2>Actions par séjour</h2><p class="muted">Cochez une action pour tester le suivi de l’équipe.</p></div><div class="content">${patients.map(x=>`<div class="task"><input type="checkbox" aria-label="Action réalisée pour ${x.id}" data-done="${x.id}" ${x.done?'checked':''}><div><strong>${esc(x.task)}</strong><div class="muted">${x.id} · ${x.specialty} · ${x.stage}</div></div><button class="secondary" data-open="${x.id}">Ouvrir le séjour</button></div>`).join('')}</div></section>`;document.querySelectorAll('[data-done]').forEach(b=>b.onchange=()=>{const x=patients.find(p=>p.id===b.dataset.done);x.done=b.checked;x.events.unshift({at:new Date().toLocaleString('fr-FR'),role,text:x.done?'Action réalisée':'Action rouverte',kind:'Action'});stats();toast('Statut de l’action mis à jour')});document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{selected=b.dataset.open;view='patients';tab='history';render()})}
function renderIntegration(){$('#workspace').innerHTML=`<div class="integration"><section class="panel"><span class="pill warn">Non connecté</span><h2 style="margin-top:16px">Emed reste la source du dossier patient</h2><p>Cette version teste le parcours de travail. Elle n’importe aucun dossier, n’envoie aucune prescription et ne s’authentifie pas auprès d’Emed.</p><h3>À cadrer avec la DSI et l’éditeur</h3><ul><li>Version d’Emed, interfaces disponibles et environnement de test.</li><li>Identité patient, identifiant du séjour et prévention des doublons.</li><li>Flux de consultation, documents, prescriptions et réalisations.</li><li>Gestion des conflits, erreurs et indisponibilités.</li></ul></section><section class="panel"><h2>Avant l’usage clinique</h2><p>Déploiement sur une infrastructure adaptée aux données de santé, authentification individuelle, droits par rôle et prise en charge, journal d’audit, sauvegardes et continuité de service.</p><p>Le moteur de recommandations de l’application existante n’est pas repris dans ce prototype. Son code source et ses règles devront être récupérés, versionnés et validés, puis intégrés séparément.</p><p>La prescription réelle nécessitera notamment un référentiel de médicaments, la validation des contrôles et du circuit de signature, ainsi qu’une qualification réglementaire selon les fonctions retenues.</p></section></div>`}
document.querySelectorAll('.nav[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});$('#role').onchange=e=>{role=e.target.value;render();toast('Profil simulé : '+role)};$('#new').onclick=()=>$('#modal').showModal();$('#close').onclick=()=>$('#modal').close();$('#newform').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);const x={id:'DÉMO-'+String(patients.length+1).padStart(3,'0'),...Object.fromEntries(f),task:'Dossier à compléter',done:false,consult:{asa:'Non renseigné',history:'',allergies:'À vérifier',treatments:'',plan:'',checks:[],validated:false},notes:[],rx:[],discharge:{summary:'',instructions:'',validated:false},events:[{at:new Date().toLocaleString('fr-FR'),role,text:'Séjour fictif créé',kind:'Dossier'}]};patients.unshift(x);selected=x.id;filter='Tous';query='';tab='overview';view='patients';$('#modal').close();render();toast('Séjour fictif créé')};
if(document.modelContext?.registerTool){const lifetime=new AbortController();const tools=[{name:'list_demo_stays',title:'Lister les séjours fictifs',description:'Retourne les séjours de démonstration de la session. Lecture seule.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(){return patients.map(({id,specialty,stage,done})=>({id,specialty,stage,done}))}},{name:'open_demo_stay',title:'Ouvrir un séjour fictif',description:'Affiche un séjour de démonstration existant dans le dossier de consultation.',inputSchema:{type:'object',properties:{id:{type:'string'}},required:['id'],additionalProperties:false},execute(input){if(!input||typeof input.id!=='string'||!patients.some(x=>x.id===input.id))throw new Error('Séjour fictif introuvable');selected=input.id;view='patients';tab='overview';render();return {id:selected,view,tab}}}];for(const t of tools){try{Promise.resolve(document.modelContext.registerTool(t,{signal:lifetime.signal})).catch(()=>{})}catch{}}window.addEventListener('pagehide',()=>lifetime.abort(),{once:true})}
